import Foundation
import Observation

@MainActor
@Observable
final class MovieListViewModel {
    private(set) var state: ViewState<[Movie]> = .idle

    private let service: any MovieService
    private var movies: [Movie] = []
    private var nextPage = 1
    private var totalPages = 1
    private var isFetching = false
    /// Bumped by `refresh()` so a page fetch that was in flight is discarded.
    private var generation = 0

    init(service: any MovieService) {
        self.service = service
    }

    func load() async {
        guard !isFetching else { return }
        if case .idle = state { await fetchNextPage(showLoading: true) }
    }

    func refresh() async {
        generation += 1
        isFetching = false
        nextPage = 1
        totalPages = 1
        // Keep the current list visible while refreshing; replace it on success.
        await fetchNextPage(showLoading: movies.isEmpty, replacing: true)
    }

    func loadNextPageIfNeeded(currentItem: Movie) async {
        guard case .loaded = state, !isFetching, nextPage <= totalPages,
              currentItem.id == movies.last?.id else { return }
        await fetchNextPage(showLoading: false)
    }

    private func fetchNextPage(showLoading: Bool, replacing: Bool = false) async {
        guard !isFetching else { return }
        isFetching = true
        let token = generation
        if showLoading { state = .loading }
        defer { if token == generation { isFetching = false } }

        do {
            let response = try await service.popular(page: nextPage)
            guard token == generation else { return }
            movies = replacing ? response.results : movies + response.results
            nextPage = response.page + 1
            totalPages = response.totalPages
            state = movies.isEmpty ? .empty : .loaded(movies)
        } catch {
            guard token == generation else { return }
            // A failed later page keeps the list on screen; it is retried on the next trigger.
            if movies.isEmpty || showLoading { state = .failed(Self.message(for: error)) }
            else if replacing { state = .failed(Self.message(for: error)) }
        }
    }

    static func message(for error: Error) -> String {
        switch error as? APIError {
        case .missingAPIKey?: "The TMDB API key is missing."
        case .httpStatus(let code, let message)?: message ?? "The server returned an error (\(code))."
        case .decoding?, .invalidResponse?: "Received an unexpected response from the server."
        case .transport?: "Could not reach the server. Check your connection and try again."
        case nil: "Something went wrong. Please try again."
        }
    }
}
EOF

